#!/usr/bin/env ruby
require 'json';require 'open3';require 'fileutils';root=File.expand_path('..',__dir__);files=Dir.glob(File.join(root,'server/**/*.java'));manual=files.select{|p|File.binread(p).include?('setAutoCommit(false)')};missing=manual.reject{|p|File.binread(p).include?('rollback()')||p.end_with?('/core/db/DataBaseMgr.java')};source=File.read(File.join(root,'server/GameCommon/src/main/java/com/aoo/bcg/common/transaction/JdbcTransactionBoundary.java'));jdk=File.expand_path('../.toolchains/jdk-26.0.2.1.jdk/Contents/Home',root);env={'JAVA_HOME'=>jdk,'PATH'=>"#{jdk}/bin:#{ENV['PATH']}"};o,e,st=Open3.capture3(env,'./mvnw','-pl','server/GameCommon','-am','-Dtest=JdbcTransactionBoundaryTest','-Dsurefire.failIfNoSpecifiedTests=false','test','-q',chdir:root);c={'manual_inventory'=>manual.length>0,'manual_rollback_present'=>missing.empty?,'checked_failure'=>source.include?('instanceof Exception'),'unchecked_failure'=>source.include?('catch(Throwable'),'rollback_failure_preserved'=>source.include?('addSuppressed'),'tests_passed'=>st.success?};r={'task'=>'JAVA03','passed'=>c.values.all?,'checks'=>c,'manualBoundaries'=>manual.map{|p|p.delete_prefix(root+'/')},'missingRollback'=>missing.map{|p|p.delete_prefix(root+'/')},'testStdout'=>o.strip,'testStderr'=>e.strip};p=File.join(root,'work/audit/transaction-rollback-semantics.json');FileUtils.mkdir_p(File.dirname(p));File.write(p,JSON.pretty_generate(r)+"\n");puts JSON.generate(r);exit(r['passed'] ? 0 : 1)
